<script setup>
import {ref} from 'vue';import pairs from '../data/history-pairs.json';import {useSequence} from '../composables/useSequence'
const base=import.meta.env.BASE_URL;const pair=ref(1);const source=ref(false);const sequence=useSequence(['Encode images and edits','Interleave paired tokens','Self-attention','Extract the query condition'])
</script>
<template><div class="stack"><div class="row spread"><div class="tabs"><button :aria-pressed="!source" @click.stop="source=false">Report · 2 layers</button><button :aria-pressed="source" @click.stop="source=true">Saved default · 4 layers</button></div><span class="small muted">8 pairs × 2 tokens + 1 query = 17 tokens</span></div><div class="transformer-pair" :class="{focused:sequence.step.value===0}"><img :src="base+pairs[pair-1].original" :alt="`Historical original ${pair}`"/><img :src="base+pairs[pair-1].edited" :alt="`Historical Expert C edit ${pair}`"/><div><h3>Historical pair {{pair}}</h3><p class="small">Shared image encoder → E{{pair}}<br>Original/target edit encoder → z{{pair}}</p></div><span class="arrow">→</span><p class="formula small">project z{{pair}} to token dimension</p></div><div class="token-strip" :class="{focused:sequence.step.value===1}" aria-label="Seventeen alternating tokens"><template v-for="i in 8" :key="i"><button :aria-pressed="pair===i" @click.stop="pair=i">E{{i}}</button><button class="z-token" :aria-pressed="pair===i" @click.stop="pair=i">z{{i}}</button></template><span class="query-token">E₀</span></div><div class="attention-route" :class="{focused:sequence.step.value===2}"><svg viewBox="0 0 1100 66" aria-label="Schematic token interactions, not measured attention"><path v-for="i in 16" :key="i" :d="`M ${22+(i-1)*65} 0 Q ${(22+(i-1)*65+1070)/2} 80 1070 0`" fill="none" :stroke="Math.ceil(i/2)===pair?'#0f62fe':'#d5dce4'" :stroke-width="Math.ceil(i/2)===pair?2:1"/></svg></div><div class="row spread" :class="{focused:sequence.step.value===3}"><div class="chips"><span v-for="i in (source?4:2)" :key="i">Transformer layer {{i}}</span></div><span class="arrow">→</span><div class="sequence-emphasis"><strong>Updated E₀ → condition c</strong><p class="small">Input to the conditional flow</p></div></div><SequenceControls :sequence="sequence"/><p class="small muted">Connections indicate possible interactions, not measured attention weights. Paired